const int ledPin = 13; // пин со встроенным светодиодом

void setup() {
  pinMode(ledPin, OUTPUT); // настраиваем пин как выход
}

void loop() {
  digitalWrite(ledPin, HIGH); // включаем светодиод (HIGH = напряжение на пине)
  delay(1000);                // ждём 1 секунду
  digitalWrite(ledPin, LOW);  // выключаем (LOW = 0 В)
  delay(1000);                // пауза перед следующим циклом
}
